220	    /**
221	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
222	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
223	     * Validation already rejects {@code null} values and the pattern-constrained fields
224	     * when blank, but {@code address} and {@code city} have no pattern, so a
225	     * whitespace-only value would otherwise slip through.
226	     *
227	     * @param ownerFieldsDto the submitted owner fields
228	     * @throws RequiredFieldsMissingException if any required field is missing or blank
229	     */
230	    /**
231	     * Common street-type abbreviations expanded during address normalization. Keys are the
232	     * upper-cased abbreviation tokens; values are their canonical expansions.
233	     */
234	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
235	        "ST", "STREET",
236	        "RD", "ROAD",
237	        "AVE", "AVENUE");
238	
239	    /**
240	     * Normalizes the submitted address on create and writes the canonical value back onto the
241	     * request so it is persisted, echoed back, and used for every downstream address comparison
242	     * (household duplicate detection and the household id). The value is trimmed, internal
243	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
244	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
245	     * {@code null} address is left untouched so the required-field check can report it as missing.
246	     *
247	     * @param ownerFieldsDto the submitted owner fields
248	     */
249	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
250	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
251	    }
252	
253	    /**
254	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
255	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
256	     * expanded to its full form. A {@code null} value is returned unchanged.
257	     *
258	     * @param raw the address to canonicalize, possibly {@code null}
259	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
260	     */
261	    private static String normalizeAddress(String raw) {
262	        if (raw == null) {
263	            return null;
264	        }
265	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
266	        if (collapsed.isEmpty()) {
267	            return collapsed;
268	        }
269	        String[] tokens = collapsed.split(" ");
270	        StringBuilder sb = new StringBuilder(collapsed.length());
271	        for (int i = 0; i < tokens.length; i++) {
272	            if (i > 0) {
273	                sb.append(' ');
274	            }
275	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
276	        }
277	        return sb.toString();
278	    }
279	
280	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
281	        List<String> errors = new ArrayList<>();
282	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
283	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
284	        requireText("address", ownerFieldsDto.getAddress(), errors);
285	        requireText("city", ownerFieldsDto.getCity(), errors);
286	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
287	        if (!errors.isEmpty()) {
288	            throw new RequiredFieldsMissingException(errors);
289	        }
290	    }
291	
292	    private static void requireText(String field, String value, List<String> errors) {
293	        if (value == null || value.isBlank()) {
294	            errors.add(field);
295	        }
296	    }
297	
298	    /**
299	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
300	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
301	     * and echoed back in that form.
302	     *
303	     * @param ownerFieldsDto the submitted owner fields
304	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
305	     *                                        valid E.164 number
306	     */
307	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
308	        String e164 = toE164(ownerFieldsDto.getTelephone());
309	        if (e164 == null) {
310	            throw new RequiredFieldsMissingException(List.of("telephone"));
311	        }
312	        ownerFieldsDto.setTelephone(e164);
313	    }
314	
315	    /**
316	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
317	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
318	     * and country code are present they are kept; otherwise country code {@code '+61'} is
319	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
320	     * must contain 8 to 15 digits after the {@code '+'}.
321	     *
322	     * @param raw the submitted telephone, possibly {@code null}
323	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
324	     */
325	    private static String toE164(String raw) {
326	        if (raw == null) {
327	            return null;
328	        }
329	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
330	        String digits;
331	        if (cleaned.startsWith("+")) {
332	            digits = cleaned.substring(1);
333	        } else {
334	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
335	            digits = "61" + national;
336	        }
337	        if (!digits.matches("[0-9]{8,15}")) {
338	            return null;
339	        }
340	        return "+" + digits;
341	    }
342	
343	    /**
344	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
345	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
346	     * each stored owner's telephone is normalized the same way before comparison so differing
347	     * input formats collapse to the same value.
348	     *
349	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
350	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
351	     *                                     same E.164 telephone
352	     */
353	    /**
354	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
355	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
356	     * the parts may contain whitespace or a second {@code @}.
357	     */
358	    private static final Pattern EMAIL_PATTERN =
359	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
360	
361	    /**
362	     * Normalizes the submitted email when present: the value is trimmed, required to be a
363	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
364	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
365	     *
366	     * @param ownerFieldsDto the submitted owner fields
367	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
368	     */
369	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
370	        String email = ownerFieldsDto.getEmail();
371	        if (email == null) {
372	            return;
373	        }
374	        String trimmed = email.strip();
375	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
376	            throw new InvalidEmailException(email);
377	        }
378	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
379	    }
380	
381	    /**
382	     * Defaults the registration date on create: when the client does not supply a
383	     * {@code registrationDate}, it is set to the server's current date so it is persisted
384	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
385	     *
386	     * @param ownerFieldsDto the submitted owner fields
387	     */
388	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
389	        if (ownerFieldsDto.getRegistrationDate() == null) {
390	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
391	        }
392	    }
393	
394	    /**
395	     * Assigns the owner's {@code customerCode} on create, formatted
396	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
397	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
398	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
399	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
400	     *
401	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
402	     */
403	    private void assignCustomerCode(Owner owner) {
404	        String city = owner.getCity();
405	        String lastName = owner.getLastName();
406	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
407	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
408	        long sequence = this.clinicService.findAllOwners().stream()
409	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
410	            .count() + 1;
411	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
412	    }
413	
414	    /**
415	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
416	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
417	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
418	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
419	     * canonicalized fields, every owner in the same household — including one joining an existing
420	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
421	     * order.
422	     *
423	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
424	     */
425	    private void assignHouseholdId(Owner owner) {
426	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
427	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
428	    }
429	
430	    /**
431	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
432	     * already share this owner's {@code firstName} and {@code lastName}, compared
433	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
434	     * pre-existing namesakes.
435	     *
436	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
437	     */
438	    private void assignNamesakeCount(Owner owner) {
439	        String firstName = owner.getFirstName();
440	        String lastName = owner.getLastName();
441	        long count = this.clinicService.findAllOwners().stream()
442	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
443	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
444	            .count();
445	        owner.setNamesakeCount((int) count);
446	    }
447	
448	    /**
449	     * Assigns the owner's {@code membershipNumber} on create, formatted
450	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
451	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
452	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
453	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
454	     *
455	     * @param owner the owner being created (with its {@code customerCode} and
456	     *              {@code registrationDate} already set)
457	     */
458	    private void assignMembershipNumber(Owner owner) {
459	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
460	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
461	    }
462	
463	    /**
464	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
465	     *
466	     * @param value the string to hash
467	     * @return the 64-character lower-case hex digest
468	     */
469	    private static String sha256Hex(String value) {
470	        try {
471	            byte[] digest = MessageDigest.getInstance("SHA-256")
472	                .digest(value.getBytes(StandardCharsets.UTF_8));
473	            StringBuilder sb = new StringBuilder(digest.length * 2);
474	            for (byte b : digest) {
475	                sb.append(String.format("%02x", b));
476	            }
477	            return sb.toString();
478	        }
479	        catch (NoSuchAlgorithmException e) {
480	            throw new IllegalStateException("SHA-256 not available", e);
481	        }
482	    }
483	
484	    private void rejectDuplicateTelephone(String normalizedTelephone) {
485	        boolean duplicate = this.clinicService.findAllOwners().stream()
486	            .map(Owner::getTelephone)
487	            .map(OwnerRestControllerV1::toE164)
488	            .filter(telephone -> telephone != null)
489	            .anyMatch(normalizedTelephone::equals);
490	        if (duplicate) {
491	            throw new DuplicateTelephoneException(normalizedTelephone);
492	        }
493	    }
494	
495	    /**
496	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
497	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
498	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
499	     * still counts as the same household. The check is skipped when the request opts in via
500	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
501	     * the existing one.
502	     *
503	     * @param ownerFieldsDto the submitted owner fields
504	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
505	     *                                     last name and address and the request did not opt in
506	     */
507	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
508	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
509	            return;
510	        }
511	        String lastName = collapse(ownerFieldsDto.getLastName());
512	        String address = collapse(ownerFieldsDto.getAddress());
513	        boolean duplicate = this.clinicService.findAllOwners().stream()
514	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
515	                && collapse(owner.getAddress()).equals(address));
516	        if (duplicate) {
517	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
518	        }
519	    }
520	
521	    /**
522	     * The maximum number of owners permitted in a single city. A create is rejected once the
523	     * owner's city already contains this many owners.
524	     */
525	    private static final long CITY_CAPACITY = 50;
526	
527	    /**
528	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
529	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
530	     * before this owner is persisted.
531	     *
532	     * @param city the submitted city
533	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
534	     */
535	    private void rejectCityAtCapacity(String city) {
536	        long count = this.clinicService.findAllOwners().stream()
537	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
538	            .count();
539	        if (count >= CITY_CAPACITY) {
540	            throw new CityAtCapacityException(city);
541	        }
542	    }
543	
544	    /**
545	     * The maximum number of owners permitted to be created in a single day. A create is
546	     * rejected once this many owners already carry today's {@code registrationDate}.
547	     */
548	    private static final long DAILY_LIMIT = 100;
549	
550	    /**
551	     * Rejects a create once {@link #DAILY_LIMIT} or more owners have already been created
552	     * today, counted by {@code registrationDate} against the server's current date. The
553	     * count is taken before this owner is persisted.
554	     *
555	     * @throws DailyOwnerLimitExceededException with a 429 status if today is already at the limit
556	     */
557	    private void rejectDailyLimit() {
558	        LocalDate today = LocalDate.now();
559	        long count = this.clinicService.findAllOwners().stream()
560	            .filter(existing -> today.equals(existing.getRegistrationDate()))
561	            .count();
562	        if (count >= DAILY_LIMIT) {
563	            throw new DailyOwnerLimitExceededException(today);
564	        }
565	    }
566	
567	    /**
568	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
569	     * every internal run of whitespace is collapsed to a single space, and the result is
570	     * lower-cased. A {@code null} value collapses to the empty string.
571	     *
572	     * @param value the value to canonicalize, possibly {@code null}
573	     * @return the collapsed, lower-cased value
574	     */
575	    private static String collapse(String value) {
576	        if (value == null) {
577	            return "";
578	        }
579	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
580	    }
581	
582	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
583	    @Override
584	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
585	        Owner owner = this.clinicService.findOwnerById(ownerId);
586	        if (owner != null) {
587	            Pet pet = owner.getPet(petId);
588	            if (pet != null) {
589	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
590	            }
591	        }
592	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
593	    }
594	}
